WITH state AS MATERIALIZED (WITH targets AS MATERIALIZED (SELECT id,matter_no FROM public.advisory_matters WHERE matter_no=ANY(ARRAY['ADV-2026-004','ADV-2026-005','ADV-2026-006','ADV-2026-007','ADV-2026-008','ADV-2026-009','ADV-2026-010','ADV-2026-011','ADV-2026-012'])),
 child_rows AS MATERIALIZED (SELECT t.matter_no,'advisory_matters' table_name,to_jsonb(c) facts FROM public.advisory_matters c JOIN targets t ON c.id=t.id UNION ALL
