SELECT t.matter_no,'advisory_journey_requests' table_name,to_jsonb(a) facts FROM public.advisory_journey_requests a CROSS JOIN targets t
 WHERE EXISTS(SELECT 1 FROM child_rows c WHERE c.matter_no=t.matter_no AND (
