 prior(id,matter_no) AS (VALUES ('8f375864-0fb3-4d17-9e07-d4f6d76cf4fe'::uuid,'ADV-2026-013'),('7583d780-9e98-4852-bf5a-98c40fbf8072'::uuid,'ADV-2026-014'),('02e5ba61-af9b-4dc0-8729-9e334639b652'::uuid,'ADV-2026-015'),('c9aa7141-ed6a-4cdd-926a-ad261fb93dd6'::uuid,'ADV-2026-016'),('47bfb55e-3ac5-445c-b335-5d48417f793e'::uuid,'ADV-2026-017'),('7442060f-5a6b-4235-a826-597a6a53bb37'::uuid,'ADV-2026-018'),('b02ba4f6-ccc8-43df-91d1-9d584ef6a7e0'::uuid,'ADV-2026-019'),('6c717f2e-aff6-44af-9774-e910d7a61047'::uuid,'ADV-2026-020'),('35583652-f594-4d7b-8f6a-24991df14dad'::uuid,'ADV-2026-021'),('50221a99-f188-4f18-9017-b6f3302a5c2f'::uuid,'ADV-2026-022'),('8cf4af68-18cd-415f-a56e-578e4ccaa2d1'::uuid,'ADV-2026-023')),installed AS (SELECT jsonb_build_object('functions',(SELECT coalesce(jsonb_object_agg(signature,evidence),'{}') FROM (
