 'policies',(SELECT coalesce(jsonb_agg(to_jsonb(p)-'schemaname'-'tablename' ORDER BY p.policyname COLLATE "C"),'[]') FROM pg_policies p WHERE p.schemaname=n.nspname AND p.tablename=c.relname),
 'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_array(t.tgname,t.tgenabled,pg_get_triggerdef(t.oid,true)) ORDER BY t.tgname COLLATE "C"),'[]') FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal ))),'{}') FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','v') AND (c.relname='advisory_matter_archives' OR c.relname IN ('advisory_operational_matters','advisory_operational_issues','advisory_operational_tasks','advisory_operational_time','advisory_operational_advice'))),
 'guards',(SELECT coalesce(jsonb_agg(jsonb_build_array(c.relname,t.tgname,t.tgenabled,pg_get_triggerdef(t.oid,true)) ORDER BY c.relname COLLATE "C",t.tgname COLLATE "C"),'[]') FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid WHERE c.relnamespace='public'::regnamespace AND t.tgname LIKE 'advisory095_%' AND c.relname<>'advisory_matter_archives'))),foundation AS (WITH journey AS (WITH rels as (select c.* from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname like 'advisory_journey_%' and c.relkind in ('r','p')),
 funcs as (select p.* from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and ((p.proname like 'advisory086_%' or p.proname like 'advisory087_%') or p.proname in ('advisory_journey_catalog','advisory_journey_manage')))
 select jsonb_build_object('tables',coalesce((select jsonb_object_agg(r.relname,jsonb_build_object('owner',pg_get_userbyid(r.relowner),'rls',r.relrowsecurity,'force_rls',r.relforcerowsecurity,'acl',r.relacl::text,
 'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated,'acl',a.attacl::text) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=r.oid and a.attnum>0 and not a.attisdropped),
 'constraints',(select coalesce(jsonb_agg(jsonb_build_object('name',conname,'definition',pg_get_constraintdef(oid,true),'validated',convalidated) order by conname collate "C"),'[]') from pg_constraint where conrelid=r.oid and contype<>'n'),
