 'advisory086_admin()',j#>ARRAY['functions','advisory086_admin()']='{"acl":"{postgres=X/postgres,authenticated=X/postgres}","owner":"postgres","config":["search_path=public"],"execute":{"anon":false,"service_role":false,"authenticated":true},"definition":"CREATE OR REPLACE FUNCTION public.advisory086_admin()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n select exists(select 1 from public.user_profiles where id=auth.uid() and role=''admin'' and active and not must_change_password);\n$function$\n","volatility":"s","security_definer":true}'::jsonb,'advisory086_immutable()',j#>ARRAY['functions','advisory086_immutable()']='{"acl":"{postgres=X/postgres}","owner":"postgres","config":["search_path=public"],"execute":{"anon":false,"service_role":false,"authenticated":false},"definition":"CREATE OR REPLACE FUNCTION public.advisory086_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''public''\nAS $function$\nbegin raise exception ''ADVISORY_JOURNEY_IMMUTABLE''; end; $function$\n","volatility":"v","security_definer":false}'::jsonb,'advisory_journey_snapshots',j#>ARRAY['tables','advisory_journey_snapshots']='{"acl":"{postgres=arwdDxtm/postgres,authenticated=r/postgres}","rls":true,"owner":"postgres","columns":[{"acl":null,"name":"matter_id","type":"uuid","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"version_id","type":"uuid","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"family_key","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"variant_id","type":"uuid","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"version","type":"integer","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"definition","type":"jsonb","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"captured_at","type":"timestamp with t