,"name":"body","type":"jsonb","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"response","type":"jsonb","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"previous_state","type":"jsonb","default":null,"identity":"","not_null":false,"generated":""},{"acl":null,"name":"resulting_state","type":"jsonb","default":null,"identity":"","not_null":false,"generated":""},{"acl":null,"name":"recorded_at","type":"timestamp with time zone","default":"clock_timestamp()","identity":"","not_null":true,"generated":""}],"indexes":["CREATE UNIQUE INDEX advisory_journey_requests_pkey ON public.advisory_journey_requests USING btree (request_id)"],"policies":[{"name":"advisory086_read","check":null,"roles":["authenticated"],"using":"advisory086_admin()","command":"r","permissive":true}],"triggers":[{"enabled":"O","definition":"CREATE TRIGGER advisory086_request_immutable BEFORE DELETE OR UPDATE ON advisory_journey_requests FOR EACH ROW EXECUTE FUNCTION advisory086_immutable()"}],"force_rls":false,"constraints":[{"name":"advisory_journey_requests_actor_id_fkey","validated":true,"definition":"FOREIGN KEY (actor_id) REFERENCES user_profiles(id)"},{"name":"advisory_journey_requests_pkey","validated":true,"definition":"PRIMARY KEY (request_id)"}]}'::jsonb) FROM journey x(j)),
