 'legacy_origin_readable',NOT EXISTS(SELECT 1 FROM public.advisory_matter_activities a JOIN public.advisory_matters m ON m.id=a.matter_id WHERE m.matter_no=ANY(ARRAY['ADV-2026-004','ADV-2026-005','ADV-2026-006','ADV-2026-007','ADV-2026-008','ADV-2026-009','ADV-2026-010','ADV-2026-011','ADV-2026-012']) AND a.kind='create'),
 'contract095_exact',f='{"guards":[["advisory_advice_records","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_advice_records FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''advisory_matter_id'')"],["advisory_deliverables","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_deliverables FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"],["advisory_issue_tasks","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_issue_tasks FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''advisory_matter_id'')"],["advisory_issues","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_issues FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''advisory_matter_id'')"],["advisory_journey_snapshots","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_journey_snapshots FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"],["advisory_matter_activities","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_matter_activities FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"],["advisory_matter_control","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_matter_control FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"],["advisory_matter_stages","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_matter_stages FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"],["advisory_matter_team","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_matter_team FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"],["advisory_matters","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_matters FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''id'')"],["advisory_stage_visits","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_stage_visits FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"],["advisory_time_logs","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_time_logs FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''advisory_matter_id'')"],["advisory_work_state_events","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_work_state_events FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"]],"functions":{"advisory095_write_guard()":{"acl":"{postgres=X/postgres}","anon":false,"owner":"postgres","config":["search_path=pg_catalog, public"],"definer":true,"definition":"CREATE OR REPLACE FUNCTION public.advisory095_write_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nDECLARE ids uuid[]; k uuid;\nBEGIN\n ids:=ARRAY[CASE WHEN TG_OP<>''DELETE'' THEN (to_jsonb(NEW)->>TG_ARGV[0])::uuid END,\n            CASE WHEN TG_OP<>''INSERT'' THEN (to_jsonb(OLD)->>TG_ARGV[0])::uuid END];\n FOR k IN SELECT DISTINCT x FROM unnest(ids) x WHERE x IS NOT NULL ORDER BY x LOOP\n  PERFORM 1 FROM public.advisory_matters WHERE id=k FOR UPDATE;\n  IF EXISTS(SELECT 1 FROM public.advisory_matter_archives WHERE matter_id=k) THEN\n   RAISE EXCEPTION ''ADVISORY_ARCHIVED'' USING ERRCODE=''55000'';\n  END IF;\n END LOOP;\n IF TG_OP=''DELETE'' THEN RETURN OLD; ELSE RETURN NEW; END IF;\nEND $function$\n","volatility":"v","service_role":false,"authenticated":false},"advisory_overdue_work(uuid)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":false,"definition":"CREATE OR REPLACE FUNCTION public.advisory_overdue_work(p_matter_id uuid DEFAULT NULL::uuid)\n RETURNS TABLE(matter_id uuid, source text, source_id uuid, title text, assignee_user_id uuid, assignee_name text, due_date date, overdue_days integer, is_next_action boolean)\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''public''\nAS $function$\ndeclare today date:=(current_timestamp at time zone ''Asia/Bangkok'')::date;\nbegin\n if not public.advisory076_allowed(''read'') then raise exception ''ADVISORY_FORBIDDEN'' using errcode=''42501''; end if;\n -- Invoker/RLS remains authoritative. Identity is (source, source_id), never title.\n return query\n with open_matters as materialized (\n  select m.id,c.next_task_id,c.next_action,c.next_owner_id,c.next_due\n  from public.advisory_operational_matters m left join public.advisory_matter_control c on c.matter_id=m.id\n  where (p_matter_id is null or m.id=p_matter_id)\n   and m.status not in (''completed'',''cancelled'') and c.closed_at is null\n )\n select m.id,''task''::text,t.id,t.title,t.assignee_user_id,\n  coalesce(nullif(p.staff_name,''''),p.full_name,t.assignee_name),t.due_date,today-t.due_date,\n  coalesce(m.next_task_id=t.id,false)\n from open_matters m join public.advisory_issue_tasks t on t.advisory_matter_id=m.id\n left join public.user_profiles p on p.id=t.assignee_user_id\n where t.deleted_at is null and t.completed_at is null\n  and t.status in (''pending'',''in_progress'',''waiting'') and t.due_date<today\n union all\n select m.id,''next_action''::text,m.id,m.next_action,m.next_owner_id,\n  coalesce(nullif(p.staff_name,''''),p.full_name),m.next_due,today-m.next_due,true\n from open_matters m left join public.user_profiles p on p.id=m.next_owner_id\n where m.next_task_id is null and nullif(btrim(m.next_action),'''') is not null and m.next_due<today;\nend; $function$\n","volatility":"s","service_role":false,"authenticated":true},"advisory095_operational(uuid)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=pg_catalog, public"],"definer":true,"definition":"CREATE OR REPLACE FUNCTION public.advisory095_operational(p_matter_id uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\n SELECT public.advisory076_allowed(''read'') AND NOT EXISTS(\n  SELECT 1 FROM public.advisory_matter_archives a WHERE a.matter_id=p_matter_id);\n$function$\n","volatility":"s","service_role":false,"authenticated":true},"advisory_workflow_checks(uuid)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":false,"definition":"CREATE OR REPLACE FUNCTION public.advisory_workflow_checks(p_matter_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''public''\nAS $function$\ndeclare m public.advisory_matters%rowtype; c public.advisory_matter_control%rowtype;\n visit public.advisory_stage_visits%rowtype; stage public.advisory_matter_stages%rowtype;\n open_tasks bigint; pending_deliverables bigint; uncompleted_stages bigint; stage_open_tasks bigint;\n has_next boolean; result jsonb; fj jsonb; options jsonb;\nbegin\n if not public.advisory076_allowed(''read'') then raise exception ''ADVISORY_FORBIDDEN'' using errcode=''42501''; end if;\n select * into m from public.advisory_operational_matters where id=p_matter_id;\n if not found then raise exception ''ADVISORY_MATTER_NOT_FOUND''; end if;\n select * into c from public.advisory_matter_control where matter_id=m.id;\n select * into visit from public.advisory_stage_visits where matter_id=m.id and kind=''visit'' and exited_at is null;\n select * into stage from public.advisory_matter_stages where id=visit.stage_id;\n select count(*) into open_tasks from public.advisory_issue_tasks where advisory_matter_id=m.id and deleted_at is null and status not in (''completed'',''cancelled'');\n select count(*) into stage_open_tasks from public.advisory_issue_tasks where advisory_matter_id=m.id and stage_id=stage.id and deleted_at is null and status not in (''completed'',''cancelled'');\n select count(*) into pending_deliverables from public.advisory_deliverables where matter_id=m.id and status not in (''delivered'',''cancelled'');\n select count(*) into uncompleted_stages from public.advisory_matter_stages s where s.matter_id=m.id and s.stage_key<>''close''\n and not exists(select 1 from public.advisory_stage_visits v where v.stage_id=s.id and\n  (v.kind=''skip'' or (v.kind=''visit'' and v.exited_at is not null)));\n select definition into fj from public.advisory_journey_snapshots where matter_id=m.id;\n if fj->''format''=''2''::jsonb then\n  select s->''outcomes'' into options from jsonb_array_elements(fj->''stages'') s where s->>''key''=stage.stage_key;\n  -- Only the actual chosen route affects closing; unchosen branches are not\n  -- incomplete work, and no skip/history is fabricated for them.\n  uncompleted_stages:=case when visit.id is null and exists(\n   select 1 from public.advisory_matter_activities a where a.matter_id=m.id and a.kind in (''stage_complete'',''stage_skip'')\n    and a.detail->>''journey_format''=''2'' and a.detail->>''next_stage_key''=''close''\n    and a.detail->>''from_visit_id''=(select v.id::text from public.advisory_stage_visits v where v.matter_id=m.id and v.kind=''visit'' order by v.entered_at desc,v.recorded_at desc,v.id desc limit 1)\n  ) then 0 else 1 end;\n end if;\n has_next:=c.next_task_id is not null or c.next_action is not null;\n result:=jsonb_build_object(''matter_id'',m.id,''version'',coalesce(c.version,0),''lifecycle'',m.status,\n  ''closed'',c.closed_at is not null or m.status in (''completed'',''cancelled''),\n  ''current_visit_id'',visit.id,''current_stage_id'',stage.id,''current_stage_key'',stage.stage_key,\n  ''current_stage_open_tasks'',stage_open_tasks,''open_tasks'',open_tasks,''has_next_action'',has_next,\n  ''pending_deliverables'',pending_deliverables,''uncompleted_stages'',uncompleted_stages,\n  ''stage_ready'',visit.id is null and uncompleted_stages=0,\n  ''legacy_without_plan'',not exists(select 1 from public.advisory_matter_stages where matter_id=m.id),\n  ''ready_to_close'',open_tasks=0 and not has_next and pending_deliverables=0 and visit.id is null and uncompleted_stages=0);\n if fj->''format''=''2''::jsonb then result:=result||jsonb_build_object(''journey_format'',2,''outcomes'',coalesce(options,''[]''::jsonb),\n  ''route_stages'',(select jsonb_agg(s-''outcomes'' order by n) from jsonb_array_elements(fj->''stages'') with ordinality x(s,n))); end if;\n return result;\nend; $function$\n","volatility":"s","service_role":false,"authenticated":true},"advisory095_archive_immutable()":{"acl":"{postgres=X/postgres}","anon":false,"owner":"postgres","config":["search_path=pg_catalog, public"],"definer":false,"definition":"CREATE OR REPLACE FUNCTION public.advisory095_archive_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nBEGIN RAISE EXCEPTION ''ADVISORY_ARCHIVE_IMMUTABLE''; END $function$\n","volatility":"v","service_role":false,"authenticated":false},"advisory_control_read(uuid,jsonb)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":false,"definition":"CREATE OR REPLACE FUNCTION public.advisory_control_read(p_matter_id uuid DEFAULT NULL::uuid, p_query jsonb DEFAULT ''{}''::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''public''\nAS $function$\ndeclare result jsonb; today date:=(current_timestamp at time zone ''Asia/Bangkok'')::date;\nbegin\n if not public.advisory076_allowed(''read'') then raise exception ''ADVISORY_FORBIDDEN'' using errcode=''42501''; end if;\n with overdue_items as materialized (select * from public.advisory_overdue_work()),\n ranked_overdue as (\n  select o.*,row_number() over(partition by matter_id order by due_date,source COLLATE \"C\",source_id) position from overdue_items o\n ), overdue as (\n  select matter_id,count(*) overdue_item_count,min(due_date) oldest_overdue_due,max(overdue_days) oldest_overdue_days,\n   coalesce(max(overdue_days) filter(where is_next_action),0) next_action_overdue_days,\n   jsonb_agg(to_jsonb(o)-''matter_id''-''position'' order by due_date,source COLLATE \"C\",source_id) filter(where position<=3) overdue_preview\n  from ranked_overdue o group by matter_id\n ), items as (\n select m.*,coalesce(o.overdue_item_count,0)>0 has_overdue_work,\n coalesce(o.overdue_item_count,0) overdue_item_count,o.oldest_overdue_due,coalesce(o.oldest_overdue_days,0) oldest_overdue_days,\n coalesce(o.next_action_overdue_days,0) next_action_overdue_days,coalesce(o.overdue_preview,''[]''::jsonb) overdue_preview,\n cl.name client_name,coalesce(c.version,0) version,c.work_state,c.closed_at,c.outcome,c.outcome_summary,c.follow_up,c.case_reference,\n c.next_task_id,coalesce(t.title,c.next_action) next_action,coalesce(t.assignee_user_id,c.next_owner_id) next_owner_id,\n coalesce(nullif(np.staff_name,''''),np.full_name,t.assignee_name) next_owner_name,coalesce(t.due_date,c.next_due) next_due,\n lead.user_id lead_id,coalesce(nullif(lp.staff_name,''''),lp.full_name,m.responsible_lawyer) lead_name,\n st.stage_key,st.template_key,v.entered_at,\n (select s->>''name_th'' from public.advisory_journey_snapshots j,lateral jsonb_array_elements(j.definition->''stages'') s where j.matter_id=m.id and s->>''key''=st.stage_key) stage_name_th,\n (select s->>''name_en'' from public.advisory_journey_snapshots j,lateral jsonb_array_elements(j.definition->''stages'') s where j.matter_id=m.id and s->>''key''=st.stage_key) stage_name_en,\n case when v.entered_at is not null then greatest(0,today-(v.entered_at at time zone ''Asia/Bangkok'')::date) end stage_days,\n greatest(0,coalesce((c.closed_at at time zone ''Asia/Bangkok'')::date,today)-coalesce(m.start_date,(m.created_at at time zone ''Asia/Bangkok'')::date)) age_days\n from public.advisory_operational_matters m join public.clients cl on cl.id=m.client_id\n left join overdue o on o.matter_id=m.id\n left join public.advisory_matter_control c on c.matter_id=m.id\n left join public.advisory_issue_tasks t on t.id=c.next_task_id and t.deleted_at is null and t.status in (''pending'',''in_progress'',''waiting'') and t.completed_at is null\n left join public.user_profiles np on np.id=coalesce(t.assignee_user_id,c.next_owner_id)\n left join public.advisory_matter_team lead on lead.matter_id=m.id and lead.team_role=''lead''\n left join public.user_profiles lp on lp.id=lead.user_id\n left join public.advisory_stage_visits v on v.matter_id=m.id and v.kind=''visit'' and v.exited_at is null\n left join public.advisory_matter_stages st on st.id=v.stage_id\n ), filtered as (\n select * from items i where (p_matter_id is null or i.id=p_matter_id)\n and (coalesce(p_query->>''search'','''')='''' or concat_ws('' '',i.matter_no,i.title,i.client_name,i.lead_name) ilike ''%''||(p_query->>''search'')||''%'')\n and (coalesce(p_query->>''client_id'','''')='''' or i.client_id::text=p_query->>''client_id'')\n and (coalesce(p_query->>''type'','''')='''' or i.matter_type=p_query->>''type'')\n and (coalesce(p_query->>''lead'','''')='''' or i.lead_id::text=p_query->>''lead'')\n and (coalesce(p_query->>''state'','''')='''' or i.work_state=p_query->>''state'')\n and case coalesce(p_query->>''tab'',''all'') when ''mine'' then exists(select 1 from public.advisory_matter_team tm where tm.matter_id=i.id and tm.user_id=auth.uid()) or i.next_owner_id=auth.uid()\n when ''overdue'' then i.has_overdue_work\n when ''missing'' then i.closed_at is null and i.next_action is null\n when ''closed'' then i.closed_at is not null else true end\n ), page as (\n select * from filtered order by case when p_query->>''sort''=''due'' then next_due end asc nulls last,created_at desc,id\n limit least(50,greatest(1,coalesce((p_query->>''limit'')::int,20))) offset greatest(0,coalesce((p_query->>''offset'')::int,0))\n ) select jsonb_build_object(''items'',coalesce((select jsonb_agg(to_jsonb(p)) from page p),''[]''),''total'',(select count(*) from filtered),\n ''summary'',(select jsonb_build_object(''open'',count(*) filter(where closed_at is null and status not in (''completed'',''cancelled'')),\n ''overdue'',count(*) filter(where has_overdue_work),''overdue_items'',coalesce(sum(overdue_item_count),0),''waiting'',count(*) filter(where closed_at is null and work_state=''waiting_client''),\n ''closed_week'',count(*) filter(where closed_at>=date_trunc(''week'',current_timestamp at time zone ''Asia/Bangkok'') at time zone ''Asia/Bangkok'')) from items),\n ''permissions'',jsonb_build_object(''manage'',public.advisory076_allowed(''manage''),''task'',public.advisory076_allowed(''task''),''delete'',public.advisory076_allowed(''delete''))) into result;\n if p_matter_id is not null then\n  if jsonb_array_length(result->''items'')<>1 then raise exception ''ADVISORY_MATTER_NOT_FOUND''; end if;\n  result:=result||jsonb_build_object(\n   ''journey_path'',(select coalesce(jsonb_agg(to_jsonb(v) order by v.entered_at,v.recorded_at,v.id),''[]''::jsonb) from public.advisory_stage_visits v where v.matter_id=p_matter_id and v.kind=''visit''),\n   ''journey_decisions'',(select coalesce(jsonb_agg(jsonb_build_object(''id'',a.id,''actor_id'',a.actor_id,''occurred_at'',a.occurred_at,''kind'',a.kind,''detail'',a.detail) order by a.occurred_at,a.id),''[]''::jsonb) from public.advisory_matter_activities a where a.matter_id=p_matter_id and a.detail->>''journey_format''=''2''),\n   ''journey_snapshot'',(select to_jsonb(j) from public.advisory_journey_snapshots j where matter_id=p_matter_id),\n   ''state_history'',(select coalesce(jsonb_agg(to_jsonb(x) order by x.started_at desc),''[]'') from (select work_state,started_at,ended_at,reason from public.advisory_work_state_events where matter_id=p_matter_id order by started_at desc limit 10) x),\n   ''team'',(select coalesce(jsonb_agg(to_jsonb(t)||jsonb_build_object(''name'',coalesce(nullif(p.staff_name,''''),p.full_name)) order by t.team_role,p.full_name),''[]'') from public.advisory_matter_team t join public.user_profiles p on p.id=t.user_id where t.matter_id=p_matter_id),\n   ''stages'',(select coalesce(jsonb_agg(to_jsonb(s)||coalesce((select element-''key'' from public.advisory_journey_snapshots j, lateral jsonb_array_elements(j.definition->''stages'') element where j.matter_id=s.matter_id and element->>''key''=s.stage_key),''{}''::jsonb)||jsonb_build_object(''visits'',coalesce(v.rows,''[]''),''minutes'',tm.minutes,''elapsed_seconds'',(select sum(extract(epoch from coalesce(exited_at,current_timestamp)-entered_at)) from public.advisory_stage_visits where stage_id=s.id and kind=''visit''),''task_total'',(select count(*) from public.advisory_issue_tasks where stage_id=s.id and deleted_at is null),''task_completed'',(select count(*) from public.advisory_issue_tasks where stage_id=s.id and deleted_at is null and status=''completed''),''unclassified'',tm.unclassified) order by s.position),''[]'')\n    from public.advisory_matter_stages s\n    left join lateral(select jsonb_agg(to_jsonb(x) order by recorded_at desc) rows from (select * from public.advisory_stage_visits where stage_id=s.id order by recorded_at desc limit 20) x) v on true\n    left join lateral(select sum(minutes) minutes,count(*) filter(where stage_id is null) unclassified from public.advisory_time_logs where advisory_matter_id=p_matter_id and stage_id=s.id and deleted_at is null) tm on true where s.matter_id=p_matter_id),\n   ''time'',(select jsonb_build_object(''minutes'',coalesce(sum(minutes),0),''core'',coalesce(sum(minutes) filter(where billable),0),''support'',coalesce(sum(minutes) filter(where not billable),0),''unclassified'',count(*) filter(where stage_id is null)) from public.advisory_time_logs where advisory_matter_id=p_matter_id and deleted_at is null),\n   ''other_matters'',(select coalesce(jsonb_agg(to_jsonb(x)),''[]'') from (select id,matter_no,title,status from public.advisory_operational_matters where client_id=(select client_id from public.advisory_operational_matters where id=p_matter_id) and id<>p_matter_id order by created_at desc limit 5) x));\n end if;\n return result;\nend; $function$\n","volatility":"s","service_role":false,"authenticated":true},"advisory_control_section(uuid,text,integer,uuid)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":false,"definition":"CREATE OR REPLACE FUNCTION public.advisory_control_section(p_matter_id uuid, p_section text, p_offset integer DEFAULT 0, p_issue_id uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''public''\nAS $function$\ndeclare tab text; predicate text; ordering text; rows jsonb; total bigint;\nbegin\n if not public.advisory076_allowed(''read'') then raise exception ''ADVISORY_FORBIDDEN'' using errcode=''42501''; end if;\n if not exists(select 1 from public.advisory_operational_matters where id=p_matter_id) then raise exception ''ADVISORY_MATTER_NOT_FOUND''; end if;\n case p_section\n when ''tasks'' then tab:=''advisory_issue_tasks''; predicate:=''advisory_matter_id=$1 and deleted_at is null and ($3 is null or advisory_issue_id=$3)''; ordering:=''case when status in (''''completed'''',''''cancelled'''') then 1 else 0 end,due_date nulls last,id'';\n when ''deleted_tasks'' then tab:=''advisory_issue_tasks''; predicate:=''advisory_matter_id=$1 and deleted_at is not null and ($3 is null or advisory_issue_id=$3)''; ordering:=''deleted_at desc,id'';\n when ''activity'' then tab:=''advisory_matter_activities''; predicate:=''matter_id=$1''; ordering:=''occurred_at desc,id'';\n when ''deliverables'' then tab:=''advisory_deliverables''; predicate:=''matter_id=$1''; ordering:=''due_date nulls last,id'';\n when ''visits'' then tab:=''advisory_stage_visits''; predicate:=''matter_id=$1''; ordering:=''recorded_at desc,id'';\n when ''states'' then tab:=''advisory_work_state_events''; predicate:=''matter_id=$1''; ordering:=''started_at desc,id'';\n else raise exception ''ADVISORY_SECTION_INVALID''; end case;\n execute format(''select count(*) from public.%I where %s'',tab,predicate) into total using p_matter_id,p_offset,p_issue_id;\n execute format(''select coalesce(jsonb_agg(to_jsonb(t)),''''[]'''') from (select * from public.%I where %s order by %s limit 20 offset $2) t'',tab,predicate,ordering)\n into rows using p_matter_id,greatest(0,p_offset),p_issue_id;\n if p_section=''tasks'' then\n  -- Enrich the existing bounded Task page from the same canonical source once.\n  with overdue as materialized (select * from public.advisory_overdue_work(p_matter_id))\n  select coalesce(jsonb_agg(t.value||jsonb_build_object(''overdue_days'',coalesce(o.overdue_days,0)) order by t.position),''[]''::jsonb)\n  into rows from jsonb_array_elements(rows) with ordinality t(value,position)\n  left join overdue o on o.source=''task'' and o.source_id=(t.value->>''id'')::uuid;\n end if;\n return jsonb_build_object(''items'',rows,''total'',total);\nend; $function$\n","volatility":"s","service_role":false,"authenticated":true}},"relations":{"advisory_matter_archives":{"acl":"{postgres=arwdDxtm/postgres,authenticated=r/postgres}","rls":true,"kind":"r","view":null,"owner":"postgres","columns":[["matter_id","uuid",true,"","",null,null],["matter_no","text",true,"","",null,null],["archived_at","timestamp with time zone",true,"","",null,null],["archived_by","uuid",true,"","",null,null],["archive_reason","text",true,"","",null,null],["request_id","uuid",true,"","",null,null],["reviewed_matter_sha256","text",true,"","",null,null],["reviewed_baseline","jsonb",true,"","",null,null]],"indexes":